/// <reference types="cypress" />
/**
 * Frame lane-local helpers (Task 9, #2841). NOT steward-owned — single-owner
 * to the frame tranche, exactly like `../range/_helpers.ts` it builds on.
 *
 * Re-exports the whole range helper surface (`visitRange`, `bffPost`/`bffGet`/
 * `bffDelete`, `createActiveExercise`, `assignExerciseRole`, `uniq`, …) so a
 * Frame spec never has to reach into `../range/_helpers` directly, then adds
 * three things this tranche owns:
 *
 *   1. `bffPatch` — moulded on `bffPost` (range/_helpers.ts:198-210): a
 *      relative `/api/v1/...` path, riding the shell-proxy session cookie
 *      (Path=/api/v1 scoped — see that file's header for why a direct
 *      range-bff :8087 call would 401).
 *   2. `setPlatformVisibility(exerciseId, map)` — PATCHes an exercise's
 *      `platform_visibility` document. `map` is TYPED as the full five-key
 *      denylist (`PlatformVisibilityMap`), mirroring
 *      `useSetPlatformVisibility.ts`'s contract ("the FULL five-key denylist
 *      map is sent on every call — never a partial patch — so intent is
 *      unambiguous on the wire"). The five keys are
 *      `DISABLEABLE_PLATFORM_IDS` in `platforms.ts` registry order (every
 *      `PlatformId` except `search`, which is never disableable).
 *   3. `seedFrameExercise()` — P6 seeds an active exercise, mints P7, and
 *      grants P7 the STUDENT exercise role, mirroring
 *      `participant-env-shell.cy.ts:36-51`'s `seedEnvExerciseAsP7` shape.
 *      Deliberately does NOT log in as P7 at the end (unlike that
 *      precedent) — callers need both personas at different points (T9
 *      drives the admin surface as P6; every other Frame test logs in as
 *      P7 itself), so the login call is left to the spec.
 *   4. `openFrameAsP7(exerciseId)` — the "log in as P7, visit the exercise
 *      env, open the Frame tab" sequence every Frame spec runs at the start
 *      of nearly every test. Collapses that repeated three-line sequence
 *      (frame-category-rail.cy.ts, frame-login.cy.ts) into one call; a spec
 *      that needs a different viewport or locale first (the overflow/RTL
 *      cases) still composes the same steps by hand instead of calling this.
 */

import type { PersonaCreds } from "../../support/commands";
import { platformButton } from "../../support/selectors";
import {
  assignExerciseRole,
  createActiveExercise,
  uniq,
  visitRange,
} from "../range/_helpers";

export * from "../range/_helpers";

const JSON_HEADERS: Record<string, string> = {
  "Content-Type": "application/json",
  Accept: "application/json",
};

/** PATCH to the range surface through the shell proxy, riding the session cookie. */
export function bffPatch(
  path: string,
  body: Cypress.RequestBody = {},
  failOnStatusCode = true,
): Cypress.Chainable<Cypress.Response<unknown>> {
  return cy.request({
    method: "PATCH",
    url: path,
    body,
    headers: JSON_HEADERS,
    failOnStatusCode,
  });
}

// ---------------------------------------------------------------------------
// Platform visibility (#1478) — the full five-key denylist map
// ---------------------------------------------------------------------------

/**
 * The full participant-visibility denylist document, one key per
 * `DisableablePlatformId` (`platformVisibility.ts` — every `PlatformId`
 * except `search`), in `platforms.ts` registry order. `useSetPlatformVisibility`
 * always sends every key on every call; this type pins the same contract at
 * the Cypress boundary so a spec cannot accidentally PATCH a partial map.
 */
export interface PlatformVisibilityMap {
  readonly kite: boolean;
  readonly porch: boolean;
  readonly commons: boolean;
  readonly frame: boolean;
  readonly courier: boolean;
}

/** PATCH an exercise's `platform_visibility` to exactly `map` (all five keys). */
export function setPlatformVisibility(
  exerciseId: string,
  map: PlatformVisibilityMap,
): Cypress.Chainable<Cypress.Response<unknown>> {
  return bffPatch(`/api/v1/range/exercises/${exerciseId}`, {
    platform_visibility: map,
  });
}

// ---------------------------------------------------------------------------
// Seeding
// ---------------------------------------------------------------------------

export interface FrameExerciseSeed {
  readonly exerciseId: string;
  /** P7's minted creds — callers that need P7 logged in call `cy.login("P7")`
   * themselves; this seed only grants the exercise role. */
  readonly p7: PersonaCreds;
}

/**
 * Seed an active exercise as P6 (creator, auto-enrolled — Range Admin/
 * instructor), mint persona P7, and grant P7 the STUDENT exercise role.
 * Mirrors `participant-env-shell.cy.ts:36-51`'s `seedEnvExerciseAsP7`, minus
 * the trailing `cy.login("P7")` — left to the caller, since some Frame specs
 * (the admin/instructor surface, T9) need to stay logged in as P6.
 */
export function seedFrameExercise(): Cypress.Chainable<FrameExerciseSeed> {
  cy.login("P6");
  const exName = uniq("Frame Env");
  return cy
    .task<PersonaCreds>("mintPersona", { persona: "P7" })
    .then((p7) =>
      createActiveExercise(exName).then((exerciseId) =>
        assignExerciseRole(exerciseId, p7.kcUserId, "student").then(
          () => ({ exerciseId, p7 }) satisfies FrameExerciseSeed,
        ),
      ),
    );
}

/**
 * Log in as P7, visit `exerciseId`'s env, and open the Frame tab — the
 * three-step sequence most Frame specs run at the top of every test (see
 * this file's header). A test that needs a viewport change or a locale
 * override BEFORE the visit (the overflow/RTL cases) composes the same
 * three steps itself instead of calling this.
 */
export function openFrameAsP7(exerciseId: string): void {
  cy.login("P7");
  visitRange(`/range/exercises/${exerciseId}/env`);
  platformButton("Open Frame").click();
}


--- frontends/cypress/cypress/e2e/frame/frame-category-rail.cy.ts (114 lines) ---
/**
 * Range journey — Frame's category rail (#2955).
 *
 * `CategoryRail` extends #2871/#2841's one-chip "All" rail into the real
 * fixture chip set (`src/fixtures/categories.ts`). Frame's own catalog
 * (`listVideos`) still always resolves to `[]` in this slice (#2846 owns
 * wiring the selection into a real filter), so every test below exercises
 * the rail itself — selection, keyboard nav, overflow, URL linkability, RTL
 * — against the standing "No videos yet" empty grid, exactly like
 * `frame-in-shell.cy.ts`'s own T1/T7 do.
 */
import { categoryChip, categoryRail, frameSurface, omnibox, platformButton } from "../../support/selectors";
import { openFrameAsP7, seedFrameExercise, visitRange } from "./_helpers";

describe("range: Frame's category rail", () => {
  it("T1: renders the full chip set with 'All' selected by default", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      openFrameAsP7(exerciseId);

      categoryRail().should("be.visible");
      categoryChip("All").should("have.attr", "aria-pressed", "true");
      categoryChip("Gaming").should("have.attr", "aria-pressed", "false");
      categoryChip("Fitness").should("be.visible");
    });
  });

  it("T2: selecting a category mirrors it into the omnibox as ?category=, and the selection is linkable", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      openFrameAsP7(exerciseId);

      categoryChip("Gaming").click();
      categoryChip("Gaming").should("have.attr", "aria-pressed", "true");
      categoryChip("All").should("have.attr", "aria-pressed", "false");
      omnibox().should("have.value", "https://frame.range/?category=gaming");

      // Linkable: typing the SAME url (e.g. from a bookmark, or pasted by
      // another participant) reproduces the same selection — the DRIVE half
      // of FrameApp.tsx's two-way address-bar bridge.
      omnibox().clear().type("frame.range/?category=gaming{enter}");
      categoryChip("Gaming").should("have.attr", "aria-pressed", "true");
    });
  });

  it("T3: re-selecting All removes ?category= from the omnibox", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      openFrameAsP7(exerciseId);

      categoryChip("Gaming").click();
      omnibox().should("have.value", "https://frame.range/?category=gaming");

      categoryChip("All").click();
      omnibox().should("have.value", "https://frame.range/");
    });
  });

  it("T4: the rail is keyboard operable end to end — Tab, Arrow keys, and Enter", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      openFrameAsP7(exerciseId);

      categoryChip("All").focus();
      categoryChip("All").should("have.focus");

      cy.focused().type("{rightarrow}");
      categoryChip("Live").should("have.focus");

      cy.focused().type("{rightarrow}");
      categoryChip("Gaming").should("have.focus");
      categoryChip("Gaming").should("have.attr", "aria-pressed", "false");

      cy.focused().type("{enter}");
      categoryChip("Gaming").should("have.attr", "aria-pressed", "true");
    });
  });

  it("T5: overflow arrows appear at a narrow viewport and are absent at a wide one", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      cy.login("P7");
      cy.viewport(1600, 900);
      visitRange(`/range/exercises/${exerciseId}/env`);
      platformButton("Open Frame").click();

      categoryRail()
        .findByRole("button", { name: /Show more categories/ })
        .should("not.exist");

      cy.viewport(360, 720);
      categoryRail()
        .findByRole("button", { name: /Show more categories/ })
        .should("be.visible");
    });
  });

  it("T6: ar-AE renders localized chip labels and mirrors the overflow chevrons", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      cy.login("P7");
      cy.viewport(360, 720);
      cy.visit(`/range/exercises/${exerciseId}/env`, {
        onBeforeLoad(win) {
          win.localStorage.setItem("omnicore.locale", "ar-AE");
        },
      });

      cy.document().its("documentElement.dir").should("eq", "rtl");
      cy.findByRole("button", { name: "فتح Frame" }).click();

      frameSurface().should("be.visible");
      categoryRail().findByRole("button", { name: "الكل" }).should("have.attr", "aria-pressed", "true");
      categoryRail()
        .findByRole("button", { name: "إظهار المزيد من الفئات" })
        .should("be.visible");
    });
  });
});


--- frontends/cypress/cypress/e2e/frame/frame-in-shell.cy.ts (153 lines) ---
/**
 * Range journey — Frame in the browser shell (#2841, PLAN.md Task 9, T1-T7).
 *
 * The first Cypress lane to exercise a Module-Federation remote served INTO
 * a second-level host (shell → range-mfe → frame-mfe) — see PLAN.md §9. There
 * is no compiled precedent to extend, so every assertion here is derived
 * straight from the live source (`FrameLayout.tsx`, `BrowseRoute.tsx`,
 * `WatchRoute.tsx`, `parseRangeUrl.ts`, `entryToOmniboxValue.ts`,
 * `PlatformHost.tsx`), not copied from an existing spec.
 *
 * ALWAYS `visitRange('/range/exercises/<id>/env')` — never the exercise-root
 * redirect (`/range/exercises/<id>`). `ExerciseRootRoute` sends a participant
 * to `firstEnabledPlatform()`'s `topLevelRoute`, which for Kite is
 * `/range/exercises/<id>/kite`, NOT `/env` — relying on the redirect landing
 * on `/env` would be flaky-by-construction (PLAN.md §9).
 *
 * frame-mfe's own catalog (`listVideos`) always resolves to `[]` in this
 * slice (#2872 hands off a real backend), so every state below is the
 * EMPTY state: no video cards exist to click, and in-surface navigation is
 * driven by the omnibox / the toolbar button / the "← Videos" back link.
 */
import {
  browserTab,
  frameSurface,
  omnibox,
  platformButton,
} from "../../support/selectors";
import { seedFrameExercise, visitRange } from "./_helpers";

describe("range: Frame in the browser shell", () => {
  it("T1: the toolbar button is focusable and opens the federated Frame surface", () => {
    seedFrameExercise().then(({ exerciseId, p7 }) => {
      cy.login("P7");
      visitRange(`/range/exercises/${exerciseId}/env`);

      // Focusable <button>, not a disabled/aria-disabled affordance.
      platformButton("Open Frame")
        .should("be.visible")
        .focus()
        .should("have.focus");

      platformButton("Open Frame").click();

      frameSurface().should("be.visible");
      // BrowseRoute's empty state: role="status", "No videos yet" — StatusNotice
      // renders no accessible name (role "status" has no name-from-content), so
      // the text assertion is against the region's content, not a role query.
      frameSurface().should("contain.text", "No videos yet");
    });
  });

  it("T2: typing frame.range into the omnibox from Kite opens Frame", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      cy.login("P7");
      visitRange(`/range/exercises/${exerciseId}/env`);

      platformButton("Open Kite").click();
      browserTab("kite").should("be.visible");

      omnibox().clear().type("frame.range{enter}");

      frameSurface().should("be.visible");
      browserTab("frame").should("be.visible");
    });
  });

  it("T3/T4: watch URL round-trip, the back link, and Back/Forward history", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      cy.login("P7");
      visitRange(`/range/exercises/${exerciseId}/env`);

      // T3 — typing a watch URL with a query string.
      omnibox().clear().type("frame.range/watch?v=8kq2nf{enter}");
      cy.findByRole("heading", { name: "Nothing to play yet", level: 1 }).should(
        "be.visible",
      );
      omnibox().should("have.value", "https://frame.range/watch?v=8kq2nf");

      // The "← Videos" back link (FrameLayout.tsx) drives the shell back to
      // Frame's home/browse path.
      cy.findByRole("link", { name: /Videos/ }).click();
      omnibox().should("have.value", "https://frame.range/");
      frameSurface().should("contain.text", "No videos yet");

      // T4 — the shell's OWN Back/Forward (NavControls), not the browser's:
      // Back restores the watch entry (omnibox regains the query string),
      // Forward returns to the home entry.
      cy.findByRole("button", { name: "Back" }).click();
      omnibox().should("have.value", "https://frame.range/watch?v=8kq2nf");

      cy.findByRole("button", { name: "Forward" }).click();
      omnibox().should("have.value", "https://frame.range/");
    });
  });

  it("T5: ar-AE keeps the omnibox dir=ltr while the document flips to rtl", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      cy.login("P7");
      cy.visit(`/range/exercises/${exerciseId}/env`, {
        onBeforeLoad(win) {
          win.localStorage.setItem("omnicore.locale", "ar-AE");
        },
      });

      cy.document().its("documentElement.dir").should("eq", "rtl");
      // The omnibox stays LTR even under RTL — URLs are semantically LTR.
      omnibox().should("have.attr", "dir", "ltr");

      cy.findByRole("button", { name: "فتح Frame" }).click();
      cy.findByRole("heading", { name: "الفيديوهات" }).should("be.visible");
    });
  });

  it("T6: the browse surface at a 360x720 viewport never overflows horizontally", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      cy.login("P7");
      cy.viewport(360, 720);
      visitRange(`/range/exercises/${exerciseId}/env`);

      platformButton("Open Frame").click();
      frameSurface().should("be.visible");

      cy.document().then((doc) => {
        expect(
          doc.documentElement.scrollWidth,
          "documentElement.scrollWidth <= clientWidth at 360x720",
        ).to.be.at.most(doc.documentElement.clientWidth);
      });
    });
  });

  it("T7: Frame renders under the persisted dark theme", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      cy.login("P7");
      // NOT the data-theme attribute flip — ThemeProvider.tsx:62,78 reads the
      // MODE from localStorage.theme on mount and derives data-theme itself;
      // setting the attribute directly would be overwritten on first render.
      cy.visit(`/range/exercises/${exerciseId}/env`, {
        onBeforeLoad(win) {
          win.localStorage.setItem("omnicore.locale", "en-US");
          win.localStorage.setItem("theme", "dark");
        },
      });

      cy.get("html").should("have.attr", "data-theme", "dark");

      platformButton("Open Frame").click();
      frameSurface().should("be.visible");
      frameSurface().should("contain.text", "No videos yet");
    });
  });
});


--- frontends/cypress/cypress/e2e/frame/frame-login.cy.ts (182 lines) ---
/**
 * Range journey — Frame's participant login (#2872: schema, reads and acting
 * identity).
 *
 * DESIGN.md's two-trust-zone model, proved end to end from the browser:
 * READS never require a `frame_session` (the video grid renders on the
 * shell's own OIDC session alone — see `frame-in-shell.cy.ts`'s empty-state
 * coverage), while ACTING as a character does. This spec is the acting-
 * identity half: a logged-out participant sees a "Login" affordance and no
 * identity chip; logging in through the in-place modal (never a route, never
 * a redirect) swaps that for the character's identity + "Log out"; invalid
 * credentials produce a localized, non-disclosing toast and leave the modal
 * open; logging out returns to the readable logged-out state.
 *
 * Every role/name/label below is copied verbatim off the live source, not
 * assumed:
 *   - `FrameTopBar.tsx`: the "Login" button (`frame_login_button`), the
 *     identity `<span aria-label={frame_logged_in_as({name})}>`, and the
 *     "Log out" button (`frame_logout`).
 *   - `FrameLoginModal.tsx`: `role="dialog"` named via an `h2` ("Log in to
 *     Frame" — `frame_login_modal_title`), the "Handle"/"Password" labeled
 *     inputs (`frame_login_handle_label`/`frame_login_password_label`), and
 *     the "Log in" submit button (`frame_login_submit`). On failure it calls
 *     `toast.danger(m.frame_login_error())` — "Invalid handle or password" —
 *     which escalates to `role="alert"` (`@omnicore-platform/ui`'s Toast
 *     primitive), and clears only the password field, never the handle.
 *
 * Credential minting: Frame has no login form of its own for PROVISIONING a
 * character — that authoring action is Kite's `POST .../credentials:generate`
 * (`kite/_helpers.ts`'s `createFaction` + `createLoginnableCharacter`, plus a
 * direct call to `:generate`, mirrored here rather than duplicated in a new
 * Frame-lane helper). This is intentional, not a gap: `frame.go`'s `Login`
 * verifies against the exact same `ParticipantCredentialServiceClientIface.
 * VerifyCredential` RPC Kite's own login uses (#2872's "D1" — one login
 * identity source for every simulated-platform surface), so any credential
 * minted for Kite logs a participant into Frame unmodified.
 */
import { createFaction, createLoginnableCharacter } from "../kite/_helpers";
import { frameSurface } from "../../support/selectors";
import { bffPost, openFrameAsP7, seedFrameExercise, uniq } from "./_helpers";

interface FrameCredential {
  readonly handle: string;
  readonly password: string;
}

/**
 * Mint a credentialed (non-synthetic) character on `exerciseId` and generate
 * its handle+password. Must run while the ACTIVE `cy.login()` session is the
 * exercise's instructor (P6 — `seedFrameExercise()` leaves that session in
 * place), since `:generate` requires RANGE_ADMIN on the exercise.
 */
function mintFrameCredential(
  exerciseId: string,
): Cypress.Chainable<FrameCredential> {
  return createFaction(exerciseId, uniq("Frame Faction")).then((factionId) => {
    const username = uniq("frameuser");
    return createLoginnableCharacter(
      exerciseId,
      factionId,
      username,
      username,
    ).then((character) =>
      bffPost(`/api/v1/kite/exercises/${exerciseId}/credentials:generate`, {
        character_id: character.id,
      }).then((resp) => {
        // range-bff wraps payloads in `{ data: ... }` through the shell
        // proxy; tolerate a bare shape too (range/_helpers.ts's own
        // `unwrap()` documents the same both-shapes tolerance).
        const body = resp.body as {
          data?: { handle?: string; password?: string };
          handle?: string;
          password?: string;
        };
        const handle = body.data?.handle ?? body.handle;
        const password = body.data?.password ?? body.password;
        expect(handle, "generated credential handle").to.be.a("string");
        expect(password, "generated credential password").to.be.a("string");
        return { handle: handle as string, password: password as string };
      }),
    );
  });
}

/** Open the Frame login modal and submit `handle`/`password`. Leaves the
 * caller to assert the outcome (success closes the dialog; failure doesn't). */
function submitFrameLogin(handle: string, password: string): void {
  frameSurface().findByRole("button", { name: "Login" }).click();
  cy.findByRole("dialog", { name: "Log in to Frame" }).within(() => {
    cy.findByLabelText("Handle").type(handle);
    cy.findByLabelText("Password").type(password);
    cy.findByRole("button", { name: "Log in" }).click();
  });
}

describe("range: Frame participant login (#2872)", () => {
  it("a logged-out participant sees the video grid with a Login affordance, no identity chip", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      openFrameAsP7(exerciseId);

      frameSurface().should("be.visible");
      frameSurface()
        .findByRole("button", { name: "Login" })
        .should("be.visible");
      frameSurface()
        .findByRole("button", { name: "Log out" })
        .should("not.exist");
    });
  });

  it("logging in through the modal reveals the character's identity and removes the Login affordance", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      // Still logged in as P6 (seedFrameExercise's instructor session) —
      // mint the credential while we hold RANGE_ADMIN on this exercise.
      mintFrameCredential(exerciseId).then(({ handle, password }) => {
        openFrameAsP7(exerciseId);

        submitFrameLogin(handle, password);

        cy.findByRole("dialog").should("not.exist");
        frameSurface()
          .findByRole("button", { name: "Log out" })
          .should("be.visible");
        frameSurface()
          .findByRole("button", { name: "Login" })
          .should("not.exist");
        // The identity chip — an `aria-label="Logged in as {name}"` span
        // (FrameTopBar.tsx) — not pinned to the exact name (display_name vs.
        // handle enrichment is an implementation detail this spec doesn't
        // own), just that the prefix the component always renders is there.
        frameSurface()
          .find('[aria-label^="Logged in as "]')
          .should("be.visible");
      });
    });
  });

  it("invalid credentials produce a non-disclosing toast and leave the modal open with only the password cleared", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      openFrameAsP7(exerciseId);

      submitFrameLogin("no-such-handle", "wrong-password");

      // Non-disclosing, localized error — "Invalid handle or password"
      // (frame_login_error), delivered via the shared danger toast
      // (role="alert").
      cy.findByRole("alert").should("contain.text", "Invalid handle or password");
      // The dialog stays open — a failed login is not a dismissal.
      cy.findByRole("dialog", { name: "Log in to Frame" }).should("be.visible");
      // Password cleared for retry; handle left in place.
      cy.findByRole("dialog").within(() => {
        cy.findByLabelText("Handle").should("have.value", "no-such-handle");
        cy.findByLabelText("Password").should("have.value", "");
      });
    });
  });

  it("logging out returns to the readable logged-out state", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      mintFrameCredential(exerciseId).then(({ handle, password }) => {
        openFrameAsP7(exerciseId);

        submitFrameLogin(handle, password);
        frameSurface()
          .findByRole("button", { name: "Log out" })
          .should("be.visible")
          .click();

        frameSurface()
          .findByRole("button", { name: "Login" })
          .should("be.visible");
        frameSurface()
          .findByRole("button", { name: "Log out" })
          .should("not.exist");
        // The video grid itself is untouched by the identity change — still
        // the standing empty state (#2846 owns wiring a real catalog).
        frameSurface().should("contain.text", "No videos yet");
      });
    });
  });
});


--- frontends/cypress/cypress/e2e/frame/frame-trending-rail.cy.ts (103 lines) ---
/**
 * Range journey — Frame's Trending rail and redesigned empty state (#2957).
 *
 * `TrendingRail` (src/components/TrendingRail.tsx) is a DELIBERATELY
 * UNWIRED placeholder — no props, no fetch of its own. `BrowseRoute.tsx`
 * renders it ONLY in the ready-with-cards branch, beside `VideoGrid`; it is
 * absent while loading, on error, and in the ready-with-zero-cards branch
 * (BrowseRoute.tsx's own header: "an unwired 'coming soon' rail makes no
 * sense next to a 'there's nothing to show you' empty state").
 *
 * As of #2872, `listVideos` is a real `GET
 * /api/v1/frame/exercises/{id}/videos` call (src/api/frame.ts,
