import type { FrameVideoDTO } from "../../../../frame-mfe/src/api/frame";

const VIDEOS_ROUTE = "**/api/v1/frame/exercises/*/videos*";

const ONE_VIDEO: FrameVideoDTO = {
  id: "vid-1",
  exercise_id: "exercise-1",
  channel_id: "chan-1",
  channel_name: "Trending Test Channel",
  title: "A Trending Test Video",
  description: "",
  media_id: "media-1",
  thumbnail_media_id: "",
  duration_seconds: 90,
  file_size_bytes: 12345,
  privacy: "PUBLIC",
  category: "",
  processing_status: "READY",
