/**
 * Range journey — Frame's category rail (#2955).
 *
 * `CategoryRail` extends #2871/#2841's one-chip "All" rail into the real
 * fixture chip set (`src/fixtures/categories.ts`). Frame's own catalog
 * (`listVideos`) still always resolves to `[]` in this slice (#2846 owns
 * wiring the selection into a real filter), so every test below exercises
 * the rail itself — selection, keyboard nav, overflow, URL linkability, RTL
 * — against the standing "No videos yet" empty grid, exactly like
 * `frame-in-shell.cy.ts`'s own T1/T7 do.
 */
import { categoryChip, categoryRail, frameSurface, omnibox, platformButton } from "../../support/selectors";
import { openFrameAsP7, seedFrameExercise, visitRange } from "./_helpers";

describe("range: Frame's category rail", () => {
  it("T1: renders the full chip set with 'All' selected by default", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      openFrameAsP7(exerciseId);

      categoryRail().should("be.visible");
      categoryChip("All").should("have.attr", "aria-pressed", "true");
      categoryChip("Gaming").should("have.attr", "aria-pressed", "false");
      categoryChip("Fitness").should("be.visible");
    });
  });

  it("T2: selecting a category mirrors it into the omnibox as ?category=, and the selection is linkable", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      openFrameAsP7(exerciseId);

      categoryChip("Gaming").click();
      categoryChip("Gaming").should("have.attr", "aria-pressed", "true");
      categoryChip("All").should("have.attr", "aria-pressed", "false");
      omnibox().should("have.value", "https://frame.range/?category=gaming");

      // Linkable: typing the SAME url (e.g. from a bookmark, or pasted by
      // another participant) reproduces the same selection — the DRIVE half
      // of FrameApp.tsx's two-way address-bar bridge.
      omnibox().clear().type("frame.range/?category=gaming{enter}");
      categoryChip("Gaming").should("have.attr", "aria-pressed", "true");
    });
  });

  it("T3: re-selecting All removes ?category= from the omnibox", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      openFrameAsP7(exerciseId);

      categoryChip("Gaming").click();
      omnibox().should("have.value", "https://frame.range/?category=gaming");

      categoryChip("All").click();
      omnibox().should("have.value", "https://frame.range/");
    });
  });

  it("T4: the rail is keyboard operable end to end — Tab, Arrow keys, and Enter", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      openFrameAsP7(exerciseId);

      categoryChip("All").focus();
      categoryChip("All").should("have.focus");

      cy.focused().type("{rightarrow}");
      categoryChip("Live").should("have.focus");

      cy.focused().type("{rightarrow}");
      categoryChip("Gaming").should("have.focus");
      categoryChip("Gaming").should("have.attr", "aria-pressed", "false");

      cy.focused().type("{enter}");
      categoryChip("Gaming").should("have.attr", "aria-pressed", "true");
    });
