        .should("not.exist");

      cy.viewport(360, 720);
      categoryRail()
        .findByRole("button", { name: /Show more categories/ })
        .should("be.visible");
    });
  });

  it("T6: ar-AE renders localized chip labels and mirrors the overflow chevrons", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      cy.login("P7");
      cy.viewport(360, 720);
      cy.visit(`/range/exercises/${exerciseId}/env`, {
