/**
 * Range journey — Frame in the browser shell (#2841, PLAN.md Task 9, T1-T7).
 *
 * The first Cypress lane to exercise a Module-Federation remote served INTO
 * a second-level host (shell → range-mfe → frame-mfe) — see PLAN.md §9. There
 * is no compiled precedent to extend, so every assertion here is derived
 * straight from the live source (`FrameLayout.tsx`, `BrowseRoute.tsx`,
 * `WatchRoute.tsx`, `parseRangeUrl.ts`, `entryToOmniboxValue.ts`,
 * `PlatformHost.tsx`), not copied from an existing spec.
 *
 * ALWAYS `visitRange('/range/exercises/<id>/env')` — never the exercise-root
 * redirect (`/range/exercises/<id>`). `ExerciseRootRoute` sends a participant
 * to `firstEnabledPlatform()`'s `topLevelRoute`, which for Kite is
 * `/range/exercises/<id>/kite`, NOT `/env` — relying on the redirect landing
 * on `/env` would be flaky-by-construction (PLAN.md §9).
 *
 * frame-mfe's own catalog (`listVideos`) always resolves to `[]` in this
 * slice (#2872 hands off a real backend), so every state below is the
 * EMPTY state: no video cards exist to click, and in-surface navigation is
 * driven by the omnibox / the toolbar button / the "← Videos" back link.
 */
import {
  browserTab,
  frameSurface,
  omnibox,
  platformButton,
} from "../../support/selectors";
import { seedFrameExercise, visitRange } from "./_helpers";

describe("range: Frame in the browser shell", () => {
  it("T1: the toolbar button is focusable and opens the federated Frame surface", () => {
    seedFrameExercise().then(({ exerciseId, p7 }) => {
      cy.login("P7");
      visitRange(`/range/exercises/${exerciseId}/env`);

      // Focusable <button>, not a disabled/aria-disabled affordance.
      platformButton("Open Frame")
        .should("be.visible")
        .focus()
        .should("have.focus");

      platformButton("Open Frame").click();

      frameSurface().should("be.visible");
      // BrowseRoute's empty state: role="status", "No videos yet" — StatusNotice
      // renders no accessible name (role "status" has no name-from-content), so
      // the text assertion is against the region's content, not a role query.
      frameSurface().should("contain.text", "No videos yet");
    });
  });

  it("T2: typing frame.range into the omnibox from Kite opens Frame", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      cy.login("P7");
      visitRange(`/range/exercises/${exerciseId}/env`);

      platformButton("Open Kite").click();
      browserTab("kite").should("be.visible");

      omnibox().clear().type("frame.range{enter}");

      frameSurface().should("be.visible");
      browserTab("frame").should("be.visible");
    });
  });

  it("T3/T4: watch URL round-trip, the back link, and Back/Forward history", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      cy.login("P7");
      visitRange(`/range/exercises/${exerciseId}/env`);

      // T3 — typing a watch URL with a query string.
      omnibox().clear().type("frame.range/watch?v=8kq2nf{enter}");
      cy.findByRole("heading", { name: "Nothing to play yet", level: 1 }).should(
        "be.visible",
      );
      omnibox().should("have.value", "https://frame.range/watch?v=8kq2nf");

      // The "← Videos" back link (FrameLayout.tsx) drives the shell back to
      // Frame's home/browse path.
      cy.findByRole("link", { name: /Videos/ }).click();
      omnibox().should("have.value", "https://frame.range/");
      frameSurface().should("contain.text", "No videos yet");

      // T4 — the shell's OWN Back/Forward (NavControls), not the browser's:
      // Back restores the watch entry (omnibox regains the query string),
      // Forward returns to the home entry.
      cy.findByRole("button", { name: "Back" }).click();
      omnibox().should("have.value", "https://frame.range/watch?v=8kq2nf");

      cy.findByRole("button", { name: "Forward" }).click();
      omnibox().should("have.value", "https://frame.range/");
    });
  });

  it("T5: ar-AE keeps the omnibox dir=ltr while the document flips to rtl", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      cy.login("P7");
      cy.visit(`/range/exercises/${exerciseId}/env`, {
        onBeforeLoad(win) {
          win.localStorage.setItem("omnicore.locale", "ar-AE");
        },
      });

      cy.document().its("documentElement.dir").should("eq", "rtl");
      // The omnibox stays LTR even under RTL — URLs are semantically LTR.
      omnibox().should("have.attr", "dir", "ltr");

      cy.findByRole("button", { name: "فتح Frame" }).click();
      cy.findByRole("heading", { name: "الفيديوهات" }).should("be.visible");
    });
  });

  it("T6: the browse surface at a 360x720 viewport never overflows horizontally", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      cy.login("P7");
      cy.viewport(360, 720);
      visitRange(`/range/exercises/${exerciseId}/env`);

      platformButton("Open Frame").click();
      frameSurface().should("be.visible");

      cy.document().then((doc) => {
        expect(
          doc.documentElement.scrollWidth,
          "documentElement.scrollWidth <= clientWidth at 360x720",
        ).to.be.at.most(doc.documentElement.clientWidth);
      });
    });
  });

  it("T7: Frame renders under the persisted dark theme", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      cy.login("P7");
      // NOT the data-theme attribute flip — ThemeProvider.tsx:62,78 reads the
      // MODE from localStorage.theme on mount and derives data-theme itself;
      // setting the attribute directly would be overwritten on first render.
      cy.visit(`/range/exercises/${exerciseId}/env`, {
        onBeforeLoad(win) {
          win.localStorage.setItem("omnicore.locale", "en-US");
          win.localStorage.setItem("theme", "dark");
        },
      });

      cy.get("html").should("have.attr", "data-theme", "dark");

      platformButton("Open Frame").click();
      frameSurface().should("be.visible");
      frameSurface().should("contain.text", "No videos yet");
    });
  });
});


