/**
 * Range journey — Frame's Trending rail and redesigned empty state (#2957).
 *
 * `TrendingRail` (src/components/TrendingRail.tsx) is a DELIBERATELY
 * UNWIRED placeholder — no props, no fetch of its own. `BrowseRoute.tsx`
 * renders it ONLY in the ready-with-cards branch, beside `VideoGrid`; it is
 * absent while loading, on error, and in the ready-with-zero-cards branch
 * (BrowseRoute.tsx's own header: "an unwired 'coming soon' rail makes no
 * sense next to a 'there's nothing to show you' empty state").
 *
 * As of #2872, `listVideos` is a real `GET
 * /api/v1/frame/exercises/{id}/videos` call (src/api/frame.ts,
 * src/lib/videoSource.ts) — this suite has no seeding path that populates
 * Frame's video catalog (that's a later slice's admin/upload surface), so
 * the two branches this spec needs (>=1 card vs. zero cards) are produced
 * with `cy.intercept` on that read, exactly as the task brief sanctions:
 * both UI states are pure functions of the `ListVideos` response shape
 * (`{videos: [...], next_page_token: ""}`), so stubbing the response is not
 * papering over a real gap — it's the only way to observe either state
 * deterministically in CI.
 */
import { frameSurface, trendingRail } from "../../support/selectors";
import { openFrameAsP7, seedFrameExercise } from "./_helpers";
import type { FrameVideoDTO } from "../../../../frame-mfe/src/api/frame";

const VIDEOS_ROUTE = "**/api/v1/frame/exercises/*/videos*";

const ONE_VIDEO: FrameVideoDTO = {
  id: "vid-1",
  exercise_id: "exercise-1",
  channel_id: "chan-1",
  channel_name: "Trending Test Channel",
  title: "A Trending Test Video",
  description: "",
  media_id: "media-1",
  thumbnail_media_id: "",
  duration_seconds: 90,
  file_size_bytes: 12345,
  privacy: "PUBLIC",
  category: "",
  processing_status: "READY",
  published_at: "2026-08-01T00:00:00Z",
  created_at: "2026-08-01T00:00:00Z",
};

/** Stub the ListVideos read with a fixed JSON body, aliased for `cy.wait`. */
function stubVideos(videos: readonly FrameVideoDTO[]): void {
  cy.intercept("GET", VIDEOS_ROUTE, {
    statusCode: 200,
    body: { videos, next_page_token: "" },
  }).as("listVideos");
}

describe("range: Frame's Trending rail and empty-state redesign (#2957)", () => {
  it("renders the Trending rail beside a non-empty video grid", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      stubVideos([ONE_VIDEO]);

      openFrameAsP7(exerciseId);
      cy.wait("@listVideos");

      frameSurface().should("be.visible");
      frameSurface().should("contain.text", ONE_VIDEO.title);

      // Named `complementary` landmark, "Trending videos" (frame_trending_rail_label).
      trendingRail().should("be.visible");
      trendingRail()
        .findByRole("heading", { name: "Trending", level: 2 })
        .should("be.visible");
      trendingRail().should(
        "contain.text",
        "Trending videos will appear here.",
      );
    });
  });

  it("shows the redesigned empty state with no Trending rail and no button, on a catalog with zero videos", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      stubVideos([]);

      openFrameAsP7(exerciseId);
      cy.wait("@listVideos");

      // The empty-state block is `role="status"` (a polite region) — assert
      // against its content the same way frame-in-shell.cy.ts's T1 does,
      // since a bare `role="status"` carries no accessible name.
      cy.findByRole("status").within(() => {
        cy.contains("No videos yet").should("be.visible");
        cy.contains(
          "Your instructor hasn't added any videos to this exercise.",
        ).should("be.visible");
      });

      // No call-to-action in the redesigned empty state — a participant
      // cannot add videos (BrowseRoute.tsx's own header).
      cy.findByRole("status").findByRole("button").should("not.exist");

      // The rail is deliberately absent alongside this empty state.
      trendingRail().should("not.exist");
    });
  });
});


