/**
 * Range journey — Frame disabled / unreachable (#2841, PLAN.md Task 9,
 * T8-T10).
 *
 * T8 (disabled platform, R7): the real gate is `navigateTo`'s wrap in
 * BrowserShell (`BrowserShell.tsx:331-352` replaces a disallowed entry with
 * `HOME_ENTRY` before `PlatformHost` ever sees it) plus the range-bff
 * participant guard — the localized `PlatformHost.tsx:105-119` panel is
 * defense-in-depth for a hypothetical bypass and is proven by Vitest, not
 * here (§4 R7). This spec asserts only the OBSERVABLE shell behaviour: the
 * toolbar tile is absent, and typing `frame.range` into the omnibox bounces
 * to the search home instead of mounting anything.
 *
 * T9 (D4a): the instructor's route to Frame CONTENT while Frame is disabled
 * for participants is the admin surface `/range/exercises/:id/admin/youtube`
 * (segment deliberately still "youtube" — the admin-surface rename is a
 * different slice, not #2841's). Zero production change; this only proves
 * the surface is reachable.
 *
 * T10 (R1): the federation-load-failure panel. Two topologies, so both are
 * intercepted — CI's real image bakes an absolute `/f/assets/remoteEntry.js`
 * (`ci-images.json` builds frame-mfe with `VITE_BASE_PATH=/f/`), while local
 * `make up`/`make dev` bakes relative chunks off the raw `localhost:5189`
 * dev-topology default (frame-mfe.yml's own `VITE_BASE_PATH: /`). Only one of
 * the two intercepts fires in any given run; both are registered so the same
 * spec is correct in CI and locally.
 */
import type { PlatformVisibilityMap } from "./_helpers";
import {
  frameSurface,
  omnibox,
  platformButton,
} from "../../support/selectors";
import { seedFrameExercise, setPlatformVisibility, visitRange } from "./_helpers";

// The FULL five-key denylist map — `useSetPlatformVisibility`'s contract is
// that every key is sent on every call, never a partial patch.
const FRAME_DISABLED: PlatformVisibilityMap = {
  kite: true,
  porch: true,
  commons: true,
  frame: false,
  courier: true,
};

describe("range: Frame disabled / unreachable", () => {
  it("T8: a disabled Frame has no toolbar entry and the omnibox bounces home", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      setPlatformVisibility(exerciseId, FRAME_DISABLED);

      cy.login("P7");
      visitRange(`/range/exercises/${exerciseId}/env`);

      platformButton("Open Frame").should("not.exist");

      omnibox().clear().type("frame.range{enter}");

      cy.findByRole("search").should("be.visible");
      frameSurface().should("not.exist");
    });
  });

  it("T9: the instructor reaches the Frame admin surface while Frame is disabled for participants", () => {
    seedFrameExercise().then(({ exerciseId }) => {
      setPlatformVisibility(exerciseId, FRAME_DISABLED);

      // P6 (creator, auto-enrolled instructor) — no frontend role exemption
      // exists (§2), so this is a DIFFERENT route entirely, not a bypass of
      // the participant gate above.
      cy.login("P6");
      visitRange(`/range/exercises/${exerciseId}/admin/youtube`);

      cy.findByRole("heading", { name: "Frame", level: 1 }).should(
        "be.visible",
      );
    });
  });

  it("T10: an unreachable remote renders the unavailable panel and leaves Kite usable", () => {
    // Both topologies (R1) — exactly one fires per environment.
    cy.intercept("GET", "**/f/assets/remoteEntry.js", {
      forceNetworkError: true,
    }).as("fPrefixRemote");
    cy.intercept("GET", "http://localhost:5189/**", {
      forceNetworkError: true,
    }).as("localPortRemote");

    seedFrameExercise().then(({ exerciseId }) => {
      cy.login("P7");
      visitRange(`/range/exercises/${exerciseId}/env`);

      platformButton("Open Frame").click();

      cy.findByRole("alert").should("be.visible");
      cy.findByRole("alert").should("contain.text", "Frame unavailable");

      // Kite is unaffected — a Frame remote failure must not take down the
      // rest of the simulated-browser shell.
      platformButton("Open Kite").click();
      cy.findByRole("feed").should("be.visible");
    });
  });
});



